import { englishAudit as previous } from './audit-english-custom-property-budget.mjs';

// Strict/non-strict CSS, table row details, captions and collapsed borders, inline svg, inline replaced elements, structural pseudo-classes, orphans/widows, flex, ::before/::after and grid, integrated together over custom-property-budget.
if (previous.length !== 877) throw new Error('Earlier English audit cardinality changed.');
export const sourceDigest = '8a4070b56fb2a1b941b3168f04e19c4aa0c521b2c4b66a5897e6a12dcf06261d';
const entries = [...previous];
entries.splice(38, 0,
  'A caption as the table\'s first child: a block above the table at the table\'s border-box width, centred by default (Chrome\'s user-agent text-align:-internal-center; it inherits the alignment when the parent sets text-align), with text properties such as font size, weight and colour, padding, borders and background; it stays with the table\'s first page fragment and does not repeat.',
  'Only as the table\'s first child and at most one (FPDF1101); inline text and br only, no p or images (FPDF1101); caption-side:bottom (FPDF1202), non-zero margins and width (FPDF1201) are not implemented; a caption whose min-content width exceeds the table\'s width fails FPDF1302, where Chrome widens the table.',
  'Bounded table structure / layout / body-row continuation');
entries.splice(42, 0,
  'Candidate source checked with NUnit (TableCaptionCollapseTests); the Chrome 158 geometry comparison runs at integration.');
entries.splice(78, 2,
  'Explicit resource-bound baseline JPEG/non-interlaced PNG (including transparency). By default an atomic inline in the line boxes of a paragraph, inline element, link, list item or table cell, aligned to the baseline (or by vertical-align), wrapping and paginating with its line; with display:block a block at root/body/report panels or a direct fixed-track table cell item, interleaved with flat paragraphs. Existing physical/percentage width, physical height, min/max and border-box constraints preserve actual image geometry and resource reuse. New in the PR #196 candidate: explicitly bound standalone and direct fixed-track td/th JPEG/PNG images resolve bounded em against the image\'s final computed font-size and rem against html root font-size, changing actual PDF matrices, paint, geometry and page movement. Not merged or released.',
  'A display:block image cannot have paragraph/inline/list ancestors (FPDF1101) and an inline image takes no margins (FPDF1201); no SVG, 16-bit/Adam7/APNG, external fetch, unsupported colors or unlimited auto-shrink. Images and decorations remain atomic; inconsistent size/row/page conditions fail. Image height percentages, calc, negatives, object-fit, implicit resource loading and image splitting remain unsupported. Structural table/col/cell em/rem sizing remains rejected; invalid value or unplaceable geometry fails while preserving prior PDF. Candidate only.');
entries.splice(117, 2,
  '1–16 columns. Without colgroup the first row sets the column count and every later row must cover it (FPDF1101). In automatic layout, percentage cell padding, image sizes or text-indent, a spanning cell with its own width, and columns whose minimum content width exceeds the available width fail FPDF1302; table-layout is not implemented (FPDF1201). No rowspan, nested tables or tables in lists (captions and collapsed borders have their own rows). Repeated headers/images remain whole, and unplaceable atomic items fail instead of producing approximate output. Fixed columns must still sum exactly to the table content width; calc and negative lengths are unsupported.');
entries.splice(126, 2,
  'Only after the tbody; td and th cells, not repeated on each page fragment; a tfoot background-color paints under its cells that have none, while its other box styles (borders, padding) still fail; display:table-row-group is accepted and changes nothing, while display:table-footer-group (a footer repeated on every fragment) fails FPDF1202; no multiple tfoot elements or table-structure recovery.',
  'Header cells in any thead, tbody or tfoot row (such as a label th next to a value td in a body row) support colspan, text/inline content, flat direct p/image items, padding, solid borders and backgrounds. The complete single-row header repeats per fragment; th text uses a real bold font role by default; centred by default as in Chrome (when the parent\'s text-align is its initial value, otherwise the parent\'s alignment is inherited).');
entries.splice(130, 1,
  'The header row may hold th and td cells; a thead background-color paints under its cells that have none and repeats with the header. No multiple header rows, rowspan, header splitting or table-structure recovery. The complete header and required decorations must fit a fresh fragment.');
entries.splice(135, 1,
  'Headers and images do not split. Body cells advance independently without repeating short values; no rowspan. Rejects atomic content that cannot fit a fresh fragment with its header/required borders. Rows accept inherited text properties and background-color (painted under cells without their own, as in Chrome), not explicit height, padding or borders; in a border-collapse:collapse table row borders take part in the collapsed border conflict resolution, while the separated model still rejects them.');
entries.splice(139, 1,
  'An inline <svg> is a replaced box (like img: by default an atomic inline in the line boxes of a paragraph, inline element, list item or td/th; a block box with display:block) drawn as PDF vector paths, never rasterised: its width/height attributes are presentational hints that CSS overrides; viewBox and preserveAspectRatio (every alignment and meet/slice/none) map into the content box, which clips the drawing; g, defs, a one-shape clipPath (userSpaceOnUse), path (the full path data grammar M/L/H/V/C/S/Q/T/A/Z, relative and absolute, implicit repeats, exponents; quadratics and arcs become cubic Béziers), rect (with rx/ry), circle, ellipse, line, polyline, polygon, title/desc; transform lists; inherited fill/fill-rule/stroke/stroke-width/stroke-linecap/stroke-linejoin/stroke-miterlimit/color/visibility/clip-rule, painted with any CSS colour (translucent colours, fill-opacity/stroke-opacity and opacity over non-overlapping shapes paint with PDF constant alpha), currentColor, none and var() substituted from the svg element\'s custom properties; clip-path=url(#id) resolves to the first element in the document with that id, and a missing id or a non-clipPath element clips nothing (as in Chrome).',
  'An svg with display:block inside a paragraph, inline element or list fails FPDF1101; margins, rounded corners and outlines on an inline svg fail FPDF1201; text, use, image, gradients, patterns, mask, filter, marker, a nested svg and style inside svg fail FPDF1102; opacity over overlapping paints or a shape that both fills and strokes (it needs a transparency group), dashed strokes, url() paint servers, percentage or unit lengths inside the svg, a percentage height, multi-shape or objectBoundingBox clipPaths, transform/clip-path on the svg element itself and malformed path data fail FPDF1103 (a browser renders the valid prefix; FactsPDF fails); CSS that would change svg content (color where currentColor paints, display, width/height on rect, custom properties declared on content, SVG properties such as fill) fails FPDF1201; every number is bounded to ±1000000, path segments count against MaxDisplayCommands (FPDF1401) and nesting against MaxDepth (FPDF1003); tracked separately from WHATWG HTML elements.',
  'Source code, unit tests and real CLI PDF checks; a Chrome 158 print-to-PDF and the FactsPDF PDF rasterised by MuPDF at 120 DPI and compared with css_visual_metrics: identical ink bounds, 40 of 187,748 ink pixels differ (0.02%, curve anti-aliasing); independent review to be confirmed separately.',
  '<math> (foreign namespace)',
  'MathML root elements are not currently accepted.');
entries.splice(145, 1);
entries.splice(242, 1,
  'currentColor is bounded to the final computed text ink, including its alpha; no opacity, blend modes, gradients, nested colour functions or image layers. Comma or slash alpha (a number or a percentage) is clamped to 0–1, rounded to n/255 as Chrome does and composited with PDF constant alpha; alpha 0 paints nothing. Existing applicable elements plus tr/thead/tbody/tfoot (painted under cells without their own background); table-cell restrictions remain; all prior HSL/RGB value limits still apply. Exception: a transparent background (including background:none) on inline text (span/b/strong/i/em/small/u/s/del/ins/a) is accepted and paints nothing; other values still fail FPDF1201.');
entries.splice(255, 2,
  'Ordinary report p/h1–h6 and div/section/article/blockquote blocks outside lists/tables may use display:none to remove their entire block subtree, or display:block to keep existing block flow. Stylesheet and inline declarations follow specificity, !important and source order. Hidden text, borders, backgrounds, margins and pagination space do not appear in the final PDF. img and svg accept display:block (a block box) and display:inline/inline-block (the default atomic inline).',
  'display:none, display:block, display:flex (single-line, row-direction flex layout, see the flex row; on ordinary report panels, li and body, and on html only as a no-op where body fills the page width) and display:grid (see the grid row), plus inline/inline-block on img/svg. CSS-wide inherit/initial/unset, inline/inline-flex/inline-grid/contents and all other display values reject, and display:flex on paragraphs or inside tables fails FPDF1201. No body/html, span, hr, list or table declarations (img/svg: see the scope; display:none on them fails FPDF1201), except that table parts accept the value they already render (table-header-group on thead, table-row-group on tbody/tfoot, table-row on tr, table-cell on td/th) and it changes nothing; every other combination of a table display keyword (including table-footer-group on tfoot and use on non-table elements) fails FPDF1202. Hidden markup still undergoes strict HTML/CSS parsing, resource checks and budgets; hiding cannot bypass validation. The HTML hidden attribute is [hidden]{display:none} on the same blocks (see attr.11); no media queries or JavaScript display.');
entries.splice(359, 2,
  'Fixed-column table td/th cells support bounded vertical-align:top/middle/bottom. Short-cell PDF text, real font baselines, direct images and their own borders are positioned within the complete painted row height. Whole rows spanning a multi-page table and intact repeated headers retain their layout. Inline img/svg accept baseline, middle, top, bottom, text-top, text-bottom, lengths and line-height percentages, aligned in their line box per CSS 2.1 (see html.img).',
  'Not general CSS vertical-align. Outside td/th and inline img/svg the initial value baseline changes no layout, so it is validated and dropped (PDF bytes equal the undeclared page) and any other value fails FPDF1201; on td/th, baseline, text-top/text-bottom, lengths and percentages fail FPDF1202, and sub/super/calc fail FPDF1202 everywhere. middle/bottom on a body row requiring independently fragmented cells fails FPDF1302 without overwriting the original PDF. No rowspan, and no vertical-align on inline text.');
entries.splice(399, 0,
  'content: a string on ::before/::after ("" makes an empty box; several strings are joined) generates the pseudo-element box, and none and normal generate nothing; content on an ordinary element changes nothing, as in a browser.',
  'content accepts only none, normal and strings (several are joined, escapes decoded); counter(), attr(), url() and quotes such as open-quote fail FPDF1202. display accepts only inline, block, flex or none (inline-block and others fail FPDF1202); block pseudo-elements only in ordinary report panels, li and body (in a paragraph or a table FPDF1201), and an inline pseudo-element takes no box properties (padding and the like fail FPDF1201); generated content on hr and other elements fails FPDF1201, and an img generates no pseudo-element box (as in a browser). ::marker, ::first-line and other pseudo-elements, pseudo-classes and selectors continuing after a pseudo-element fail FPDF1203; structural pseudo-classes such as :not(:empty) are not implemented. Errors leave the previous PDF untouched.',
  'CSS selectors, cascade and PDF layout of generated boxes',
  'Candidate-source NUnit (GeneratedContentTests: divider geometry, inline text before and after, block pseudo-elements, no-output cases and failure codes) and a comparison with Chrome print output (word origins within 0.12pt horizontally, divider fills within 0.37pt); test suites not run locally, exact CI, independent review and main still to be confirmed.');
entries.splice(407, 3,
  'separate is the zero-spacing separated model (PDF bytes identical to an undeclared page); collapse implements Chrome\'s CSS 2.1 collapsing border model: hidden wins, then the wider border, then solid over dashed over dotted, then cell over row, row group and table, and between equal boxes the one further left or up; cells and the table lay out with half of each collapsed border, table padding is ignored, and borders are painted centred on the grid lines; tr/thead/tbody/tfoot borders take part in the conflict resolution; at a page break each fragment paints half of the broken line, and a repeated header repeats the table\'s top border with it.',
  'Column and column group borders are not supported (FPDF1201); a row that must split across pages fails FPDF1302 in the collapsing model; non-zero border-spacing still fails FPDF1202; Chrome rounds fractional-pixel border widths, FactsPDF uses the exact width; other values fail FPDF1202.');
entries.splice(411, 0,
  'Candidate-source NUnit: the initial value produces PDF bytes identical to the undeclared page, other values fail FPDF1202 and write no output; cell border boxes touch without spacing, which is the separated model with zero spacing. Exact CI, independent review and main are verified separately.');
entries.splice(415, 2,
  'caption-side:top (including CSS-wide keywords, !important and any letter case) is validated and dropped: a caption is already placed above its table, so the PDF bytes match the undeclared page.',
  'bottom and other values still fail FPDF1202; a caption below the table is not supported.');
entries.splice(433, 0,
  'orphans and widows are inherited positive integers on any block (CSS-wide keywords, !important, stylesheet or style attribute), 2 (the CSS initial value) where undeclared, acting on the lines of paragraphs, headings, pre, anonymous panel text, list items and cell paragraphs of table rows that split across pages: at a page break at least orphans lines stay at the bottom of the page and at least widows lines start the next, at the breaks Chrome prints. When the page already holds content, a paragraph that cannot keep its orphans moves whole to the next page (with its panel\'s leading padding/border or list marker); otherwise it breaks where the page ends. The break moves earlier for the widows but never below the orphans, and the orphans are kept when both cannot be. A break-after:avoid heading group moves only when the paragraph after it cannot keep its orphans.',
  'The initial value 2 changes the earlier line-by-line breaks: a page no longer ends with a paragraph\'s lone first line or starts with its lone last line, and a break-after:avoid heading no longer moves its whole group when two lines of its paragraph fit after it (orphans:1;widows:1 restores the old breaks). A later cell paragraph that cannot keep its orphans moves to the next page within its cell; one that starts its cell\'s fragment moves the whole row. Table rows that fit a fresh page still move whole (an existing difference from Chrome). Values above 32767 compute to 32767 as in Chrome; 0, negative, non-integer, length, other keyword and calc() values fail FPDF1202. Validated and dropped on inline text, br, img, hr and col. No multi-column or other fragmentation containers. Errors do not overwrite the previous PDF.',
  'Candidate-source NUnit: Chrome-printed page-split comparisons (paragraphs, lists, headings and 13 table-cell cases), a 4,050-layout line-order sweep, byte equality and FPDF1202 rejections; the author compared synthetic pages with Chrome\'s printed breaks one by one. Exact CI, independent review, the output change against main (Parity-Expect: orphans-widows-initial-2) and main are verified separately.');
entries.splice(439, 6,
  'The flex shorthand (none, auto, one number as the grow factor with a 0% basis, or grow shrink basis) sets a flex item\'s flex-grow, flex-shrink and flex-basis; widths are resolved with the CSS flexible-length algorithm in a single-line row container, content sizes measured from the real PDF glyphs.',
  'Only single-line (flex-wrap:nowrap), row-direction (flex-direction:row) display:flex, on ordinary report panels, li and body; each inline child and each run of text between them is its own flex item, and a flex li has no list marker and is not numbered; html{display:flex} is accepted only as a no-op where body fills the page width, otherwise FPDF1201. A row is never split across pages: when it does not fit the rest of the page it moves to the next page only if every item is a single paragraph of at most three lines (which a browser also moves whole), otherwise, and for a row taller than a page or items that cannot shrink to the container, FPDF1302. wrap, column and reverse directions, inline-flex, display:flex on paragraphs or inside tables and tables as flex items fail FPDF1201/FPDF1202; align-content does nothing in a single-line container and is validated and dropped; errors leave the previous PDF untouched.',
  'CSS parsing, cascade and real PDF flex layout',
  'Candidate-source NUnit (FlexLayoutTests: exact Courier geometry, alignment, shrinking, pagination and failure codes) and a word-origin comparison with Chrome print output (horizontal differences at most 0.28pt, vertical differences the same as for the same content in plain block flow); test suites not run locally, exact CI, independent review and main still to be confirmed.',
  'flex-direction accepts only row (the initial value, with CSS-wide keywords and the flex-flow shorthand): a display:flex container lays its children out left to right in one row.',
  'flex-wrap accepts only nowrap (the initial value, with CSS-wide keywords and the flex-flow shorthand): every flex item stays on one line and shrinks by flex-shrink when the row overflows.',
  'flex-grow takes a nonnegative number: flex items share the container\'s free width in proportion, within min-width/max-width, with the freezing loop of the CSS flexible-length algorithm.',
  'flex-shrink takes a nonnegative number: when the row is too wide, items shrink in proportion to shrink factor times base size, never below their min-content width (the automatic minimum) or min-width.',
  'flex-basis: auto (the width, else the max-content width), content, lengths, percentages of the container width and em/rem; with box-sizing:border-box it includes padding and borders.',
  'align-items and align-self: normal/stretch (boxes and images stretch to the line height), flex-start/start/self-start, flex-end/end/self-end, center and baseline (first-line baselines, the border-box bottom for an item without text); the container\'s height or min-height sets the line height.',
  'justify-content: normal/flex-start/start/left/stretch, flex-end/end/right, center, space-between, space-around and space-evenly; auto margins take the free space first, and column-gap inserts a fixed gap between items.',
  'The gap shorthand sets row-gap and column-gap: normal, a nonnegative length, a percentage of the container width or em/rem, one or two values; a display:flex container inserts the column gap between adjacent flex items, and other elements are unaffected (as in a browser).',
  'A single-line flex container has one line, so the row gap has no effect; a grid container inserts the gaps between its columns and rows (the row gap is dropped at a page break); no multi-column gaps; negative values, auto and more than two values fail FPDF1202.',
  'CSS parsing, cascade and spacing between flex items',
  'row-gap: normal, nonnegative lengths, percentages and em/rem are validated and accepted; a single-line flex container has one line, so no row gap is inserted (as in a browser).',
  'Negative values, auto and other values fail FPDF1202; a grid container inserts the row gap between its rows (dropped at a page break); no multi-line flex or multi-column row gaps.',
  'column-gap: normal, a nonnegative length, a percentage of the container width or em/rem; a display:flex container inserts it between adjacent flex items, and other elements are unaffected (as in a browser).',
  'Negative values, auto and other values fail FPDF1202; no multi-column layout gaps.',
  'display:grid on ordinary report panels, li and body makes a grid container: grid-template-columns defines the column tracks and the items (inline children and the text between them too) are auto-placed row by row into auto-sized rows; the grid shorthand itself is not accepted.',
  'repeat(), minmax(), fit-content(), content-keyword tracks, named lines, explicit placement and inline-grid fail FPDF1202; grid on html, paragraphs or tables, height/min-height and break-inside:avoid on a grid container, and table items fail FPDF1201; columns that cannot fit fail FPDF1302; no grid areas and no grid shorthand.',
  'CSS parsing, cascade and grid layout',
  'Source and NUnit tests (GridLayoutTests); the full test suite passes on net8/net9/net10 on the integration branch; the geometry comparison with Chrome 158 is in the integration PR',
  'Lengths, percentages, em/rem, fr and auto tracks (track sizing for single-span items: min-content first, auto grows to max-content, fr shares the leftover space, justify-content:normal stretches auto tracks); none is a single implicit auto column.',
  'grid-template-rows at its initial value none (CSS-wide keywords included) is validated and accepted: items are auto-placed row by row into auto-sized rows, as in a browser.',
  'Other grid-template-rows values (explicit row tracks, explicit placement or areas) fail FPDF1202; repeat(), minmax(), fit-content(), content-keyword tracks, named lines, explicit placement and inline-grid fail FPDF1202; grid on html, paragraphs or tables, height/min-height and break-inside:avoid on a grid container, and table items fail FPDF1201; columns that cannot fit fail FPDF1302; no grid areas and no grid shorthand.',
  'grid-area at its initial value auto (CSS-wide keywords included) is validated and accepted: items are auto-placed row by row into auto-sized rows, as in a browser.',
  'Other grid-area values (explicit row tracks, explicit placement or areas) fail FPDF1202; repeat(), minmax(), fit-content(), content-keyword tracks, named lines, explicit placement and inline-grid fail FPDF1202; grid on html, paragraphs or tables, height/min-height and break-inside:avoid on a grid container, and table items fail FPDF1201; columns that cannot fit fail FPDF1302; no grid areas and no grid shorthand.',
  'grid-column at its initial value auto (CSS-wide keywords included) is validated and accepted: items are auto-placed row by row into auto-sized rows, as in a browser.',
  'Other grid-column values (explicit row tracks, explicit placement or areas) fail FPDF1202; repeat(), minmax(), fit-content(), content-keyword tracks, named lines, explicit placement and inline-grid fail FPDF1202; grid on html, paragraphs or tables, height/min-height and break-inside:avoid on a grid container, and table items fail FPDF1201; columns that cannot fit fail FPDF1302; no grid areas and no grid shorthand.',
  'grid-row at its initial value auto (CSS-wide keywords included) is validated and accepted: items are auto-placed row by row into auto-sized rows, as in a browser.',
  'Other grid-row values (explicit row tracks, explicit placement or areas) fail FPDF1202; repeat(), minmax(), fit-content(), content-keyword tracks, named lines, explicit placement and inline-grid fail FPDF1202; grid on html, paragraphs or tables, height/min-height and break-inside:avoid on a grid container, and table items fail FPDF1201; columns that cannot fit fail FPDF1302; no grid areas and no grid shorthand.');
entries.splice(621, 6,
  ':root matches the document root (html in HTML) with pseudo-class specificity (0,1,0); the structural pseudo-classes :first-child, :last-child, :only-child, :first-of-type, :last-of-type, :only-of-type, :nth-child(), :nth-last-child(), :nth-of-type(), :nth-last-of-type() (odd/even and CSS Syntax An+B) and :empty match as in Chrome and count as classes in specificity; sibling counts include style, br and the dropped script/template, document-level content goes into head or body as the HTML parser puts it, and unwritten html/head/body match too; :empty treats whitespace-only text as content (as Chrome does).',
  'The "of S" form, :lang, :hover and other pseudo-classes, and An+B values beyond ±1000000000 fail FPDF1203 (::before/::after: see the pseudo-element row); repeated html/head/body tags with attributes fail FPDF1101; unsupported declarations in matching rules still fail; failures keep the previous PDF.',
  'Real PDF cascade matching of pseudo-classes (source)',
  'Source, NUnit tests (StructuralPseudoClassTests, RootPseudoClassTests, ImpliedDocumentElementTests) and a Chrome 158 Element.matches()/computed-colour differential',
  ':not() takes compound selector list arguments (such as :not(:empty), :not(.a, #b) and nested :not()), with the specificity of its most specific argument; matching agrees with Chrome and takes part in the cascade, !important and the CSS matching budget.',
  'Combinators inside :not() (complex selectors, which Chrome accepts), empty arguments and :is()/:where()/:has() fail FPDF1203; :not() nested or with more than 32 arguments fails FPDF1205; failures keep the previous PDF.',
  'Negation pseudo-class matching in the real PDF cascade (source).',
  'Source, NUnit tests (StructuralPseudoClassTests) and a Chrome 158 Element.matches()/computed-colour differential',
  '::before and ::after (and the legacy :before and :after) generate a box at the start or end of an element\'s content: string content makes inline text by default, and a block box inside a display:flex container or with display:block/flex on the pseudo-element, which takes part in its parent\'s layout with width, height, borders, backgrounds and flex-grow (such as flex-grow:1 divider lines either side of a title). A pseudo-element inherits from its element, cascades its own rules and counts as a type selector in specificity; pseudo-element rules without content (such as *::before{box-sizing:border-box}) generate nothing.');
entries.splice(632, 1,
  'Inline svg now renders, but svg|… namespace selectors and @namespace are still unsupported.');
entries.splice(642, 3,
  'Strict mode (the default) rejects recovery diagnostics and invalid CSS. The opt-in non-strict mode (.NET WithStrict(false), CLI --strict false) drops CSS that is invalid per the specifications exactly as a browser handles CSS errors (unknown properties and at-rules, values the property grammar does not accept, invalid selector lists together with their whole rule, CSS syntax errors, style elements whose type is not CSS; a var() declaration invalid at computed-value time computes as unset) and reports each as a warning with the code, message and location strict mode would throw; the PDF bytes equal the page with that CSS removed.',
  'Only CSS proven invalid is dropped (superset grammars and name lists checked against Chrome 158 CSSOM); valid CSS that is not implemented (such as position:absolute, :hover, @font-face, display:inline-grid) and every resource limit fail in both modes; values that cannot be proven invalid (properties without a grammar table, values holding a known function, values valid in quirks mode) fail as before; declarations written directly inside @media still fail (Chrome drops the following rule together with them); at most MaxCssWarnings warnings are stored.',
  'Source code, unit tests, Chrome 158 CSSOM and real CLI PDF bytes checked; independent review confirmed separately.');
entries.splice(673, 1,
  'Where a browser would unset the declaration at computed-value time (a reference with no value and no fallback, a used reference cycle, a value the property rejects after substitution) strict mode fails with FPDF1202 (or the code the literal value would get) and non-strict mode computes it as unset with a warning; a substitution that yields one CSS-wide keyword (inherit/initial/unset/revert/revert-layer) applies as that keyword, as in Chrome 158; revert/revert-layer on a custom property act as unset (inherit); losing declarations are substituted and checked too; malformed var() fails FPDF1202 at parse time; each substituted value holds at most MaxCssSyntaxNodes syntax nodes, reference chains are at most MaxCssSyntaxDepth deep and substitution work counts against MaxCssMatchOperations (FPDF1205); a page may use at most MaxCssCustomProperties distinct custom property names (default 4096, a repeated name counts once; FPDF1205 beyond it); var() in SVG paint attributes is substituted from the svg element\'s computed custom properties; no var() in selectors or at-rule preludes, and no @property registration.');
entries.splice(872, 2);
entries.splice(885, 1,
  'No unsupported PNG/JPEG modes, SVG image resources (inline svg is drawn as vector paths; see the svg element row), implicit URL/path/data loading, unconstrained auto-shrink or image fragments. Resource and geometry budgets, intrinsic-ratio checks and output protection apply. Image height percentages, calc, negatives, object-fit, implicit resource loading and image splitting remain unsupported. Structural table/col/cell em/rem sizing remains rejected; invalid value or unplaceable geometry fails while preserving prior PDF. Candidate only.');
entries.splice(912, 1,
  'Current source implementations accept 71 CSS property names. Font-size/line-height and bounded root-relative and element-relative report box lengths/paragraph margins affect real PDF geometry and pagination. Text-indent, letter-spacing and word-spacing accept scoped em/rem, with text spacing limited to 0–24pt. Div/section/article panels support bounded outside vertical margins and margin:0 auto horizontal centring without repeating margins on continued page fragments. Negative margins, margin collapse, vertical percent/auto and calc reject. Four LTR-only shorthands (margin-inline, margin-block, padding-inline, padding-block) and eight LTR-only logical side longhands (margin-inline-start, margin-inline-end, margin-block-start, margin-block-end, padding-inline-start, padding-inline-end, padding-block-start, padding-block-end) map to the same real physical box geometry and per-side important/CSS-wide cascade. RTL and vertical writing are not supported. Body/list/table/image/inline margins and unsupported relative border/image/table/column values retain their limits. Numeric font-weight accepts hundred-step values 100–900, mapping to caller-supplied normal/bold roles. Bounded text-align:justify, overflow-wrap:break-word and min/max-width remain strict subsets; this is not complete CSS support. Scoped display:block/none now applies only to ordinary non-list/non-table report blocks. A hidden block disappears before PDF font/layout/paint, while all hidden input and resources remain strictly validated; all other display values and elements fail explicitly. Bounded list-style-type adds decimal, alphabetic, Roman, vector-disc and marker-free choices on ol/ul/li, with true PDF gutters and strict rejection. It is not full CSS Lists. Bounded ASCII text-transform:capitalize changes actual PDF glyphs, line layout and pagination while preserving mixed-case word tails and inline word boundaries. No Unicode capitalization or full CSS Text support. The bounded CSS list marker subset now includes background-transparent hollow circles and solid vector squares on ol/ul/li; no full CSS Lists implementation. Bounded one-token list-style shorthand now supports the nine existing list-style-type marker kinds or a CSS-wide value on ol/ul/li, using the real PDF marker path, not inside/images/counters. Positive ASCII ordinals 1–999999 with ol start, reversed and direct-li value count marker-free items too. Underflow and invalid values preserve existing output. This is not full CSS Lists or a binary release. Bounded text-align:start/end now selects the actual left/right horizontal PDF text positions in LTR reports, including inherited styles, measured fonts and page continuation. It does not accept RTL, direction or vertical writing, and is not a full CSS Text implementation. Bounded solid/none/dashed/dotted CSS border values now produce real independently coloured PDF strokes with per-page pattern resets, preserving legacy solid PDF bytes. No double, rounded corners or background clipping and no new accepted CSS property name. Scoped td/th vertical-align:top/middle/bottom moves short-cell text and images inside whole rows without moving cell paint. middle/bottom on fragmented body rows is rejected; no baseline, rowspan or full CSS Tables support. Now 71 bounded CSS property names. As of 2026-11-01, text-decoration-color and text-decoration-style and a single-line text-decoration shorthand produce real glyph-measured, paginated opaque PDF decoration strokes; no combined lines, double/wavy, alpha, arbitrary thickness or full CSS Text Decoration. Now 71 bounded CSS property names. As of 2026-11-01, ordinary report cards now support a one-to-four physical border-radius (zero or 0.25–72pt) for real PDF Bezier background and uniform solid border-ring paint, with first/last-page fragment caps; no percentages, elliptical slash or separate per-corner longhands, asymmetric/patterned border or inline/table/image/list radius. There are now 72 scoped CSS property names. As of 2026-11-01, one to four physical border-radius values now paint distinct clockwise corners of real PDF report backgrounds and uniform border rings; narrow page fragments proportionally fit curves. Elliptical slash radii and separate corner CSS longhands are unsupported. There are still 72 scoped CSS property names. As of 2026-11-01, scoped min-height now reserves real PDF report-panel height, with physical/em/rem lengths, content-box/border-box, explicit failure protection and 72 supported CSS names in the current source. Height/max-height and general CSS Sizing remain unsupported. New 2026-11-01 source-only independent corner-radius longhands at 16b235a85b57159b3b7ac2182b38487b6a22f6eb: four physical per-corner CSS names genuinely paint PDFs, with 50-card native byte equivalence to shorthand and strict errors. Current total is 80 scoped CSS property names across 418 stable records; no prior binary or customer release changes. As of 2026-11-02 the accepted inventory is 80 scoped CSS property names in 418 stable records. Actual PDF section page breaks and legacy auto/always aliases work only on documented ordinary panels and explicit paragraphs/headings; heading-only avoid remains restricted. General Paged Media, inside/left/right and list/table/inline breaks remain unsupported. Source feature, final-head CI, independent review, human approval and customer distribution are separate. As of 2026-11-02, 418 stable audit records now cover 80 scoped CSS property names. A strictly one-page fixed-height card really reserves PDF paint and text space; overflow, percentages, general sizing and table/list/inline height fail safely. This is source-only, with current CI, independent review, packaging, human page approval and customer distribution rights separate. As of 2 November 2026, 418 stable records cover 80 bounded CSS property names. Scoped word-break:break-all fills the remaining PDF line with supported simple glyphs, including flat table-cell paragraphs, with explicit invalid-input and output-preservation guarantees; this is not Unicode shaping or full CSS Text. Source-only capability does not relabel the private preview or establish CI, independent review, human approval or customer rights. As of 2 November 2026, explicitly bound standalone and direct td/th images support bounded min/max-width and border-box sizing that changes actual PDF matrices and page movement. No image rem/em, CSS height/object-fit, implicit shrink or URL fetching. The 418 records and 80 scoped CSS property names remain unchanged; held private binaries and customer rights are not updated. As of 2 November 2026 bounded physical CSS image height is supported on bound standalone/direct fixed-column td/th JPEG/PNG images: auto width uses native aspect ratio, two specified axes can stretch deliberately, and border-box deducts vertical padding/borders. Percent/em/rem height, object-fit and implicit shrink are unsupported. All 418 stable records and 80 scoped CSS property names remain; implementation source 7afae6b5 does not re-label the old preview or grant customer rights. As of 2 November 2026 explicitly bound JPEG/PNG images support bounded physical min-height/max-height (pt, px, mm, cm, in and zero), with max-height:none reset. Auto height preserves intrinsic pixel aspect when vertical limits apply; explicit height may independently size the PDF matrix. Border-box counts vertical edges once, and incompatible width/height constraints fail without overwriting an earlier PDF. Report panels do not support max-height; percentages, em/rem, calc and object-fit remain unsupported for images. The 418 audit records and 81 scoped CSS property names are retained; this is not general CSS Sizing. Incremental 2 November 2026 scoped break-inside:auto/avoid and legacy page-break-inside: only top-level report sign-off cards with at most eight direct nonempty text paragraphs/headings move intact on measured PDF page boundaries; not nested/list/table/image, fixed/min-height, over-one-page cards or full CSS Paged Media. The 418 stable records are retained with 83 scoped CSS property names. Public source is not an installable preview or customer licence. Current 2 November 2026 source supersedes the older blanket vertical-percent exclusion: div/section/article/blockquote panels and standalone hr now accept nonnegative vertical percentage margin lengths, resolved from the containing block content width, including physical and LTR margin-block shorthands and longhands. Paragraph/heading percentages and direct inherit still reject. Negative/auto/calc, margin collapsing and unsupported targets remain excluded; 418 records and 83 bounded CSS names remain. Source 0518b51d7a34457798c748db6753c4270ce20996 is not new customer software or a rights grant. Six additional LTR-only border shorthand names are now accepted, with actual PDF stroke, geometry, cascade and pagination: border-inline, border-block and inline/block start/end. The accepted CSS name count is now 89 (previously 83) while all 418 capability IDs remain stable. The earlier six-shorthand note predates these 18 component names. Bounded LTR logical border width/style/colour pairs and single sides now have actual PDF paint and layout: accepted CSS name count is now 107 (previously 89), preserving 418 stable IDs. No RTL, vertical writing or complete CSS Borders. As of 4 November 2026, single @media print/all blocks run supported styles through the real PDF renderer. Screen/compound/conditional/nested media and other at-rules are not implemented. The 418 audited records and 107 bounded CSS property names remain unchanged. As of 5 November 2026, bounded text-decoration-thickness supports auto or 0.2–12pt resolved physical/em/rem lengths and an optional fourth shorthand term. Unsupported percent/from-font/calc and out-of-scope targets reject. All 418 stable IDs remain; accepted bounded CSS property names increase from 107 to 108, not full CSS Text Decoration or a distributed package. As of 5 November 2026, bounded text-underline-offset accepts auto or actual nonnegative 0–24pt physical/em/rem values for PDF underlines only. Negative, percent, calc, from-font and standalone images reject. The 418 stable feature IDs remain unchanged; the accepted scoped CSS names increase from 108 to 109 without claiming complete CSS Text Decoration. On 5 November 2026, bounded list-style-position inside/outside and two-term list-style shorthand gained real PDF marker positioning. All 418 stable IDs remain; accepted scoped CSS property names increase from 109 to 110. On 5 November 2026, bounded report panel outlines added five physical CSS names (outline, width/style/color/offset), raising scoped accepted spellings from 110 to 115. Real PDF outside-box paint and paginated edges are limited to ordinary panels, not lists/tables. On 5 November 2026, bounded text-align-last added one CSS property spelling (115 to 116), with final/forced line alignment in printable report text and flat fixed-column cells, not full CSS Text. On 17 November 2026, the legacy word-wrap alias of overflow-wrap added one CSS property spelling (116 to 117). On 17 November 2026, nine property names accepted only at their initial value (position, float, clear, overflow, overflow-x, overflow-y, visibility, z-index, opacity) took the count from 117 to 126. Five more names accepted only at none (box-shadow, text-shadow, transform, filter, background-image) took it from 126 to 131. Four names that only affect pointer interaction on a screen and have no effect on a PDF page (cursor, pointer-events, user-select, resize) accept a single keyword value, which is validated and dropped; this took it from 131 to 135. print-color-adjust and its common prefixed spelling -webkit-print-color-adjust accept exact or economy, which is validated and dropped because colours and backgrounds are always painted exactly as declared; this took it from 135 to 137. Three more names that only control screen glyph rasterisation and have no effect on a PDF file (text-rendering, -webkit-font-smoothing, -moz-osx-font-smoothing) accept a single keyword value, which is validated and dropped; this took it from 137 to 140. text-size-adjust and its common prefixed spelling -webkit-text-size-adjust only control automatic font inflation in mobile browsers and accept auto, none or a non-negative percentage, which is validated and dropped; this took it from 140 to 141. appearance and its -webkit-/-moz- spellings only switch native form-control styling, which the renderer never draws, and accept a single keyword value, which is validated and dropped; this took it from 141 to 142. backface-visibility (also spelled -webkit-backface-visibility; it only matters for 3D-transformed elements, and transform accepts only none) and touch-action (which only selects screen touch gestures) accept a single keyword value, which is validated and dropped; this took it from 142 to 144. will-change only tells a browser compositor which features are about to animate, and a written PDF page never changes, so it accepts auto or a comma-separated list of property names, which is validated and dropped; this took it from 144 to 145. transition and its transition-property, -duration, -timing-function, -delay and -behavior longhands only animate a change of computed value on screen, and a written PDF page is never restyled, so a well-formed transition list is validated and dropped; this took it from 145 to 151. animation and its animation-name, -duration, -timing-function, -delay, -iteration-count, -direction, -fill-mode and -play-state longhands only run on screen, and a written PDF page shows no keyframe, so a well-formed animation list is validated and dropped, as is a well-formed @keyframes rule; this took it from 151 to 160. scroll-behavior, overscroll-behavior and its -x, -y, -inline and -block longhands, overflow-anchor, -webkit-overflow-scrolling and scrollbar-width only steer a scroll container, and a PDF page never scrolls (overflow accepts only visible), so a single keyword value is validated and dropped; this took it from 160 to 169. caret-color, accent-color, -webkit-tap-highlight-color, scrollbar-color and scrollbar-gutter only style a text caret, native form controls, the tap highlight and scrollbars, which a PDF page does not have, so auto, their keywords or well-formed colours (alpha allowed, since nothing is painted) are validated and dropped; this took it from 169 to 174. -webkit-box-sizing and -moz-box-sizing are the legacy engine spellings of box-sizing and share its cascade slot, values and applicability; this took it from 174 to 176. -ms-text-size-adjust and -moz-text-size-adjust (normalize.css v3/v4) are prefixed aliases of text-size-adjust with the same values and are validated and dropped; this took it from 176 to 178. color-scheme and forced-color-adjust only let a browser pick dark user-agent defaults or opt out of a forced high-contrast palette; a PDF page has no preferred or forced scheme and paints every colour as declared, so well-formed values are validated and dropped; this took it from 178 to 180. clip-path and backdrop-filter at none, mix-blend-mode:normal and isolation:auto are initial values; normal flow clips, blends and isolates nothing, so they are validated and dropped while other values still fail FPDF1202; this took it from 180 to 184. -webkit-/-moz-border-radius, -webkit-/-moz-box-shadow, -webkit-/-moz-/-ms-/-o-transform, -webkit-filter, -webkit-clip-path and -webkit-backdrop-filter are the legacy engine spellings of the standard properties and share their values, cascade slot, applicability and errors; this took it from 184 to 195. -webkit-/-moz-/-ms-user-select are prefixed aliases of user-select, and -webkit-user-drag, -webkit-touch-callout and -ms-overflow-style only steer screen dragging, the iOS long-press callout and the legacy Edge/IE scrollbar, which a PDF page does not have, so their keywords are validated and dropped while other values fail FPDF1202; this took it from 195 to 201. font-feature-settings (with its -webkit-/-moz- aliases), font-variation-settings, font-variant-ligatures, font-variant-numeric and font-stretch at normal, font-optical-sizing:auto and font-size-adjust:none are initial values; the renderer applies no OpenType features, variation axes, optical sizing, aspect adjustment or width selection beyond the font as given, so they are validated and dropped while other values still fail FPDF1202; this took it from 201 to 210. color-adjust is the deprecated alias of print-color-adjust, and tab-size (with -moz-tab-size) accepts a non-negative number or length that is validated and dropped, because no tab stop reaches a PDF page (collapsed tabs become spaces and preserved tabs fail FPDF1305), while other values fail FPDF1202; this took it from 210 to 213. zoom:normal (or 1/100%), contain:none, content-visibility:visible and auto for line-break, text-justify and image-rendering are initial values; the renderer scales, contains and skips nothing, and line breaking, justification and image interpolation are already its own choice, so they are validated and dropped while other values still fail FPDF1202; this took it from 213 to 219. speak accepts the CSS Speech keywords and the CSS 2 aural keywords (none, normal, spell-out) that icon-font stylesheets still write; the renderer speaks nothing, so they are validated and dropped while other values fail FPDF1202; this took it from 219 to 220. text-decoration-skip-ink accepts auto or none and font-synthesis accepts none: the renderer synthesizes no bold or italic face and never breaks an underline around descenders, which is what those values allow, so they are validated and dropped while text-decoration-skip-ink:all and other font-synthesis values fail FPDF1202; this took it from 220 to 222. The legacy text-decoration-skip (with its -webkit- alias, which normalize.css 7 and Bootstrap 4 write as objects on links) accepts none, auto or objects: no image or other atomic inline can sit inside a line, so it is validated and dropped while ink, spaces, edges and other values fail FPDF1202; this took it from 222 to 224. -webkit-text-decoration and its -line, -color and -style longhands are aliases of the standard names, sharing their cascade slots, values and errors; this took it from 224 to 228. font-variant and its -caps, -east-asian, -alternates and -position longhands at normal are initial values; the renderer substitutes no small caps, East Asian forms, alternates or sub/superscript glyphs, so they are validated and dropped while other values still fail FPDF1202; this took it from 228 to 233. font-language-override, font-variant-emoji and font-palette at normal and text-emphasis and text-emphasis-style at none are initial values; the renderer applies no language-specific glyph forms, emoji presentation switches or palettes and draws no emphasis marks, so they are validated and dropped while other values still fail FPDF1202; this took it from 233 to 238. direction at ltr, unicode-bidi at normal, writing-mode at horizontal-tb, text-orientation at mixed and text-combine-upright at none are initial values; the renderer lays out only left-to-right horizontal text and never reorders, rotates or combines glyphs, so they are validated and dropped while rtl, isolate, vertical-rl and other values still fail FPDF1202; this took it from 238 to 243. column-count, column-width and columns at auto, column-gap at normal, column-span, column-rule and column-rule-style at none and column-fill at balance are initial values; the renderer always lays out a single column, so they are validated and dropped while column-count:2 and other values still fail FPDF1202; this took it from 243 to 251. text-overflow at clip, line-clamp and -webkit-line-clamp at none and box-decoration-break and -webkit-box-decoration-break at slice are initial values; no box clips its overflow and a box split across pages already paints as slices, so they are validated and dropped while ellipsis, clone and other values still fail FPDF1202; this took it from 251 to 256. rotate, scale, translate and perspective at none, transform-style at flat and mask, mask-image, -webkit-mask, -webkit-mask-image and shape-outside at none are initial values; like transform:none they move nothing, and no mask or float shape is ever applied, so they are validated and dropped while rotate:45deg, preserve-3d, url() and other values still fail FPDF1202; this took it from 256 to 266. hanging-punctuation at none, hyphenate-character and text-underline-position at auto and text-spacing-trim at normal are initial values; the renderer hangs no punctuation, hyphenates nothing automatically, trims no CJK spacing and places underlines itself, so they are validated and dropped while first, trim-start, under and other values still fail FPDF1202; this took it from 266 to 270. background-attachment at scroll, background-blend-mode at normal, background-origin at padding-box, container-type at normal and container at none are initial values; the renderer never paints a background image and evaluates no container query, so they are validated and dropped while fixed, multiply, content-box, inline-size and other values still fail FPDF1202; this took it from 270 to 275. aspect-ratio at auto, mask-repeat at repeat, mask-size at auto, mask-origin and mask-clip at border-box, mask-mode at match-source, mask-composite at add and mask-type at luminance are initial values; images always keep their pixel aspect ratio, other boxes have no preferred ratio and no mask is ever applied, so they are validated and dropped while 16 / 9, no-repeat, cover, alpha and other values still fail FPDF1202; this took it from 275 to 283. scroll-margin and scroll-padding with their ten side and axis longhands only offset a scroll-into-view target, and a PDF page is never scrolled to an anchor, so well-formed offsets (lengths for scroll-margin; auto, non-negative lengths or percentages for scroll-padding) are validated and dropped while auto for scroll-margin, negative padding, calc() and too many components still fail FPDF1202; this took it from 283 to 305. scroll-snap-type, scroll-snap-align and scroll-snap-stop only decide where a scroll container comes to rest, and a PDF page never scrolls, so their keyword forms are validated and dropped while other values or orders still fail FPDF1202; this took it from 305 to 308. animation-composition:replace, animation-timeline and view-timeline-inset at auto, animation-range and its -start/-end longhands at normal, scroll-timeline, view-timeline and their -name longhands, timeline-scope, view-transition-name and view-transition-class at none, and scroll-timeline-axis and view-timeline-axis at block are validated against their initial value and dropped, because no animation runs and a PDF page is never scrolled or navigated, while other values still fail FPDF1202; this took it from 308 to 323. anchor-name, anchor-scope, position-area, position-try, position-try-fallbacks and overlay at none and position-try-order at normal are validated against their initial value and dropped, because every box stays in normal flow and nothing reaches a top layer, while other values still fail FPDF1202; this took it from 323 to 330. interpolate-size:numeric-only, reading-flow:normal, field-sizing:fixed, dynamic-range-limit:no-limit and caret, caret-animation and caret-shape at auto are validated against their initial value and dropped, because nothing animates, no text caret is drawn, form fields keep fixed sizing and colours are never mapped to a high-dynamic-range display, while other values still fail FPDF1202; this took it from 330 to 337. text-wrap-style and text-box-edge at auto, text-box-trim at none and text-box, paint-order, math-style and math-shift at normal are validated against their initial value and dropped, because lines break greedily, line boxes are never trimmed, glyphs carry no stroke and no MathML layout runs, while other values still fail FPDF1202; this took it from 337 to 344. contain-intrinsic-size and its -width, -height, -block-size and -inline-size longhands at none and transform-box at view-box are validated against their initial value and dropped, because size containment and transforms never apply, while other values still fail FPDF1202; this took it from 344 to 350. font-kerning at auto or none is validated and dropped, because the renderer never kerns, while normal and other values still fail FPDF1202; this took it from 350 to 351. top, right, bottom, left, inset and the six logical inset properties at auto, and border-image and border-image-source at none, are validated against their initial value and dropped, because offsets never move a position:static box and no border image is painted, while other values still fail FPDF1202; this took it from 351 to 364; well-formed transform-origin and -webkit-transform-origin values are validated and dropped, because only transform:none is accepted and no box is ever transformed, while other values still fail FPDF1202; this took it from 364 to 366; font-synthesis-weight, font-synthesis-style, font-synthesis-small-caps and font-synthesis-position at none are validated and dropped like the shorthand, because no bold, italic, small-caps or super/subscript face is ever synthesized, while auto and other values still fail FPDF1202; this took it from 366 to 370; border-collapse:separate and border-spacing at one or two zero lengths are validated and dropped as initial values, because cell border boxes already touch without spacing (the separated model with zero spacing), while collapse and non-zero spacing still fail FPDF1202; this took it from 370 to 372; empty-cells:show and caption-side:top are validated and dropped as initial values, because empty cells already paint and no caption element is accepted, while other values still fail FPDF1202; this took it from 372 to 374; offset-path:none, offset-rotate and offset-anchor at auto, initial-letter:normal and text-emphasis-color:currentcolor are validated and dropped as initial values, because no box is placed along a motion path, no drop cap is drawn and no emphasis mark is painted, while other values still fail FPDF1202; this took it from 374 to 379; quotes at auto, none, match-parent or pairs of strings is validated and dropped, because no q element or quote generated content is accepted and no quotation mark is ever inserted, while other values still fail FPDF1202; this took it from 379 to 380; gap and row-gap at normal are validated as initial values and dropped, because no flex, grid or multi-column container exists and no gap is ever inserted, while other values still fail FPDF1202; this took it from 380 to 382; font-family as a family list is validated and dropped, because no system font is ever discovered and the supplied font chain is the only installed font, while other values still fail FPDF1202; this took it from 382 to 383; the non-standard background-color-adjust is an alias of print-color-adjust like color-adjust, so exact or economy is validated and dropped because backgrounds and colours are always painted as declared, while other values still fail FPDF1202 and -webkit-background-color-adjust still fails FPDF1201; this took it from 383 to 384; orphans and widows are inherited positive integers, 2 where undeclared, that set how many lines of a paragraph stay at the bottom of a page and start the next, at the breaks Chrome prints, and non-positive or non-integer values fail FPDF1202; this took it from 384 to 386; display:flex lays out single-line, row-direction flex containers, adding flex, flex-direction, flex-wrap, flex-flow, flex-grow, flex-shrink, flex-basis, justify-content, align-items, align-self, align-content and order (twelve names), and gap, row-gap and column-gap now take lengths and percentages; this took it from 386 to 398; string content on ::before and ::after generates pseudo-element boxes, adding the content name; this took it from 398 to 399; display:grid lays out grid containers, adding grid-template-columns, justify-items and justify-self and, at their initial values, grid-template-rows, grid-template-areas, grid-auto-flow, grid-auto-rows, grid-auto-columns, grid-column, grid-row, grid-area, grid-column-start, grid-column-end, grid-row-start and grid-row-end (fifteen names); this took it from 399 to 414.');
export const englishAudit = Object.freeze(entries);
if (englishAudit.length !== 916 ||
  englishAudit.some(value => typeof value !== 'string' || !value.trim() || /[㐀-鿿]/u.test(value)))
  throw new Error('Incomplete English audit layer.');
